\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usetikzlibrary{shapes.geometric,calc,positioning}
\pagestyle{empty}

% ── World Bank Institutional Color Theme ──
\definecolor{primary}{HTML}{0C4A6E}      % Deep institutional blue
\definecolor{secondary}{HTML}{0E7490}    % Teal
\definecolor{accent}{HTML}{B45309}       % Amber/gold
\definecolor{bgposter}{HTML}{EFF6FF}     % Light blue-gray background
\definecolor{tealbg}{HTML}{F0FDFA}       % Teal card tint
\definecolor{bluebg}{HTML}{EFF6FF}       % Blue card tint
\definecolor{darkbg}{HTML}{FEF3C7}       % Warm cream card tint
\definecolor{accentbg}{HTML}{FFFBEB}     % Amber card tint
\definecolor{tealtitlebg}{HTML}{CCFBF1}  % Teal card title bg
\definecolor{bluetitlebg}{HTML}{DBEAFE}  % Blue card title bg
\definecolor{darktitlebg}{HTML}{FDE68A}  % Primary card title bg
\definecolor{accenttitlebg}{HTML}{FEF3C7}% Accent card title bg
\definecolor{textdark}{HTML}{111827}     % Main text
\definecolor{textgray}{HTML}{4B5563}     % Secondary text
\definecolor{stathighlight}{HTML}{FEF3C7}% Amber stat highlight bg
\definecolor{riskred}{HTML}{991B1B}      % Deep red for risk emphasis
\definecolor{riskbg}{HTML}{FEF2F2}       % Light red risk card tint
\definecolor{risktitlebg}{HTML}{FECACA}  % Risk card title bg

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=20pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Card styles ──
\tcbset{
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=tealbg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=tealtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=accenttitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.18},
  },
  riskcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=riskbg,
    borderline west={6pt}{0pt}{riskred},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{riskred},
    coltitle=riskred, colbacktitle=risktitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={riskred!50},
    valign=top, drop shadow={opacity=0.22},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!18!white,
    borderline west={6pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.22},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

% ════════════════════════════════════════════
% ══ TITLE BAR ══
% ════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=6pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{64}{78}\selectfont\bfseries Global Economic Prospects}\\[8pt]
  {\fontsize{36}{44}\selectfont Resilience Amid Uncertainty}\\[6pt]
  {\fontsize{24}{30}\selectfont\color{white!75} World Bank Group \quad$\vert$\quad June 2025}
}

% ════════════════════════════════════════════
% ══ STAT BANNER ══
% ════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!12!white, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=6pt, bottom=6pt,
  valign=center, borderline south={3pt}{0pt}{primary!30},
]{name=stats, column=1, span=2, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{accent!50}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{52}{64}\selectfont\bfseries\color{accent} 6 Decades}\\[3pt]
      {\fontsize{20}{26}\selectfont\color{textdark} Strongest Recovery Since 1960s}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{secondary!50}{tealbg}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{52}{64}\selectfont\bfseries\color{secondary} 1.2B}\\[3pt]
      {\fontsize{20}{26}\selectfont\color{textdark} Youth Entering Working Age (Next Decade)}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.30\linewidth}\centering
    \fcolorbox{primary!50}{bluebg}{\parbox{0.88\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{52}{64}\selectfont\bfseries\color{primary} 1.5B}\\[3pt]
      {\fontsize{20}{26}\selectfont\color{textdark} People Targeted for Health Services by 2030}\vspace{6pt}%
    }}
  \end{minipage}
}

% ════════════════════════════════════════════
% ══ LEFT COLUMN ══
% ════════════════════════════════════════════

% ── A Historic Recovery — But Uneven ──
\posterbox[darkcard, title={A Historic Recovery --- But Uneven}
]{name=recovery, column=1, between=row5 and row9}{
  \fontsize{24}{32}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item Post-2020 recovery unmatched in six decades
    \item Vulnerable EMDEs lag significantly behind advanced economies
    \item Global growth projected to edge downward this year
    \item Firms scaling back inventory accumulation
  \end{itemize}
  \vspace{4pt}
  \colorbox{primary!18}{\parbox{0.93\linewidth}{%
    \fontsize{22}{28}\selectfont\color{primary}\textbf{Key concern:}
    \color{textdark} Growth could falter further if trade tensions escalate or financial sentiment deteriorates sharply.%
  }}
}

% ── Policy Actions for Sustained Growth ──
\posterbox[tealcard, title={Policy Actions for Sustained Growth}
]{name=policy, column=1, between=row9 and row15}{
  \fontsize{22}{28}\selectfont
  \renewcommand{\arraystretch}{1.5}
  \centering
  \begin{tabular}{>{\bfseries\color{secondary}}p{0.22\linewidth} p{0.34\linewidth} p{0.34\linewidth}}
    \rowcolor{secondary!15}
    \color{secondary}\fontsize{20}{26}\selectfont\textbf{Reform Area} &
    \color{secondary}\fontsize{20}{26}\selectfont\textbf{Global Action} &
    \color{secondary}\fontsize{20}{26}\selectfont\textbf{Domestic Action} \\
    \rowcolor{tealbg}
    Trade & Improve multilateral trade environment & Diversify partners \& products \\
    \rowcolor{white!80!tealbg}
    Finance & Ease external financing for EMDEs & Strengthen macro frameworks \\
    \rowcolor{tealbg}
    Climate & Scale up risk mitigation & Invest in resilient infrastructure \\
    \rowcolor{white!80!tealbg}
    Investment & Catalyze private capital flows & Remove structural bottlenecks \\
    \rowcolor{tealbg}
    Jobs & Support labor mobility & Enhance skills \& market flexibility \\
  \end{tabular}
  \vspace{4pt}
  \colorbox{secondary!20}{\parbox{0.93\linewidth}{%
    \fontsize{20}{26}\selectfont\color{secondary}\textbf{1.2 billion youth} entering working age
    --- job creation is central to the Bank's mission.%
  }}
}

% ── Key Research Themes ──
\posterbox[bluecard, title={Key Research Themes}
]{name=research, column=1, between=row15 and row20}{
  \fontsize{22}{28}\selectfont
  \renewcommand{\arraystretch}{1.4}
  \centering
  \begin{tabular}{>{\bfseries\color{accent}}p{0.28\linewidth} p{0.66\linewidth}}
    \rowcolor{accent!15}
    \color{accent}\fontsize{20}{26}\selectfont\textbf{Theme} &
    \color{accent}\fontsize{20}{26}\selectfont\textbf{Selected Topics} \\
    \rowcolor{accentbg}
    Fiscal Policy & Fiscal rules (Jan.\ 2026); small states (June 2024) \\
    \rowcolor{white!80!accentbg}
    Trade & High trade costs (June 2021); COVID-19 \& value chains (June 2020) \\
    \rowcolor{accentbg}
    Commodities & Price cycles (Jan.\ 2022); energy implications (June 2022) \\
    \rowcolor{white!80!accentbg}
    Financial & Rising U.S.\ rates (June 2023); rapid debt buildup (Jan.\ 2020) \\
    \rowcolor{accentbg}
    Pandemics & COVID-19 \& inequality (Jan.\ 2022); macro effects (June 2020) \\
  \end{tabular}
}

% ════════════════════════════════════════════
% ══ RIGHT COLUMN ══
% ════════════════════════════════════════════

% ── Risks to the Outlook (VISUAL WEIGHT) ──
\posterbox[riskcard, title={Risks to the Outlook}
]{name=risks, column=2, between=row5 and row12}{
  \fontsize{24}{32}\selectfont

  % Risk 1: Trade Tensions
  \fcolorbox{riskred!50}{riskred!10}{\parbox{0.93\linewidth}{%
    \vspace{4pt}%
    {\fontsize{26}{32}\selectfont\bfseries\color{riskred} Trade Tensions}\\[3pt]
    {\fontsize{22}{28}\selectfont\color{textdark}
    Escalating tariffs and retaliatory measures disrupt supply chains and dampen investment.}%
    \vspace{4pt}%
  }}
  \vspace{6pt}

  % Risk 2: Financial Volatility
  \fcolorbox{riskred!50}{riskred!10}{\parbox{0.93\linewidth}{%
    \vspace{4pt}%
    {\fontsize{26}{32}\selectfont\bfseries\color{riskred} Financial Market Volatility}\\[3pt]
    {\fontsize{22}{28}\selectfont\color{textdark}
    Deteriorating sentiment could tighten financing conditions, especially for EMDEs.}%
    \vspace{4pt}%
  }}
  \vspace{6pt}

  % Risk 3: Inventory Correction
  \fcolorbox{accent!50}{accent!10}{\parbox{0.93\linewidth}{%
    \vspace{4pt}%
    {\fontsize{26}{32}\selectfont\bfseries\color{accent} Inventory Correction}\\[3pt]
    {\fontsize{22}{28}\selectfont\color{textdark}
    Firms that front-loaded purchases are drawing down stocks, reducing near-term demand.}%
    \vspace{4pt}%
  }}
  \vspace{6pt}

  % Risk 4: Climate Shocks
  \fcolorbox{accent!50}{accent!10}{\parbox{0.93\linewidth}{%
    \vspace{4pt}%
    {\fontsize{26}{32}\selectfont\bfseries\color{accent} Climate Shocks}\\[3pt]
    {\fontsize{22}{28}\selectfont\color{textdark}
    Extreme weather threatens agricultural output and infrastructure in vulnerable regions.}%
    \vspace{4pt}%
  }}
}

% ── World Bank 2030 Strategic Priorities ──
\posterbox[highlightcard, title={World Bank 2030 Strategic Priorities}
]{name=priorities, column=2, between=row12 and row20}{
  \fontsize{24}{32}\selectfont

  % Priority 1: Health
  \fcolorbox{white!60!primary}{white}{\parbox{0.93\linewidth}{%
    \vspace{3pt}%
    {\fontsize{38}{46}\selectfont\bfseries\color{accent} 1.5 Billion People}\quad
    {\fontsize{20}{26}\selectfont\color{textdark} Health Services --- quality, affordable care}%
    \vspace{3pt}%
  }}
  \vspace{5pt}

  % Priority 2: Electricity
  \fcolorbox{white!60!primary}{white}{\parbox{0.93\linewidth}{%
    \vspace{3pt}%
    {\fontsize{38}{46}\selectfont\bfseries\color{secondary} 300 Million People}\quad
    {\fontsize{20}{26}\selectfont\color{textdark} Mission 300 --- electricity in Sub-Saharan Africa}%
    \vspace{3pt}%
  }}
  \vspace{5pt}

  % Priority 3: Agriculture
  \fcolorbox{white!60!primary}{white}{\parbox{0.93\linewidth}{%
    \vspace{3pt}%
    {\fontsize{38}{46}\selectfont\bfseries\color{secondary} 300 Million Farmers}\quad
    {\fontsize{20}{26}\selectfont\color{textdark} AgriConnect --- up the agricultural value chain}%
    \vspace{3pt}%
  }}
  \vspace{5pt}

  % Priority 4: Women
  \fcolorbox{white!60!primary}{white}{\parbox{0.93\linewidth}{%
    \vspace{3pt}%
    {\fontsize{38}{46}\selectfont\bfseries\color{accent} 80 Million Women}\quad
    {\fontsize{20}{26}\selectfont\color{textdark} Capital Support --- access to capital for women-led businesses}%
    \vspace{3pt}%
  }}
  \vspace{5pt}

  % Priority 5: Water
  \fcolorbox{white!60!primary}{white}{\parbox{0.93\linewidth}{%
    \vspace{3pt}%
    {\fontsize{38}{46}\selectfont\bfseries\color{primary} 1B+ People}\quad
    {\fontsize{20}{26}\selectfont\color{textdark} Water Forward --- 400M WBG commitment to water security}%
    \vspace{3pt}%
  }}
}

\end{tcbposter}
\end{document}

