\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usetikzlibrary{shapes.geometric,calc,positioning}
\pagestyle{empty}

% ── World Bank Institutional Color Theme ──
\definecolor{primary}{HTML}{0C4A6E}      % Deep institutional blue
\definecolor{secondary}{HTML}{0E7490}    % Teal
\definecolor{accent}{HTML}{B45309}       % Amber/gold
