  label={\color{primary}\bfseries\arabic*.}}

% ── Warning triangle icon for risk items ──
\newcommand{\riskicon}{%
  \begin{tikzpicture}[baseline=-2pt, scale=0.7]
    \node[regular polygon, regular polygon sides=3, fill=riskred, draw=riskred,
      minimum size=14pt, inner sep=0pt] {};
    \node[font=\fontsize{10}{12}\selectfont\bfseries\color{white}] {!};
  \end{tikzpicture}%
}
\newcommand{\warnicon}{%
  \begin{tikzpicture}[baseline=-2pt, scale=0.7]
