    coltitle=accent, colbacktitle=accenttitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.18},
  },
  riskcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=riskbg,
    borderline west={7pt}{0pt}{riskred},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{riskred},
    coltitle=riskred, colbacktitle=risktitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=3pt, titlerule style={riskred!60},
    valign=top, drop shadow={opacity=0.25},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!15!white,
    borderline west={6pt}{0pt}{primary},
