]

% ════════════════════════════════════════════
% ══ TITLE BAR ══
% ════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{68}{82}\selectfont\bfseries Global Economic Prospects}\\[8pt]
  {\fontsize{38}{46}\selectfont Resilience Amid Uncertainty}\\[6pt]
  {\fontsize{24}{30}\selectfont\color{white!75} World Bank Group \quad$\vert$\quad June 2025}
}

