% ── A Historic Recovery — But Uneven ──
\posterbox[darkcard, title={A Historic Recovery --- But Uneven}
]{name=recovery, column=1, between=row5 and row9}{
  \fontsize{26}{34}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item Post-2020 recovery unmatched in six decades
    \item Vulnerable EMDEs lag significantly behind advanced economies
    \item Global growth projected to edge downward this year
    \item Firms scaling back inventory accumulation
  \end{itemize}
  \vspace{6pt}
  \colorbox{primary!20}{\parbox{0.93\linewidth}{%
    \fontsize{23}{30}\selectfont\color{primary}\textbf{Key concern:}
    \color{textdark} Growth could falter further if trade tensions escalate or financial sentiment deteriorates sharply.%
  }}
}

% ── Policy Actions for Sustained Growth ──
\posterbox[tealcard, title={Policy Actions for Sustained Growth}
]{name=policy, column=1, between=row9 and row15}{
  \fontsize{22}{28}\selectfont
  \renewcommand{\arraystretch}{1.6}
  \centering
  \begin{tabular}{>{\bfseries\color{secondary}}p{0.20\linewidth} p{0.36\linewidth} p{0.36\linewidth}}
    \rowcolor{secondary!15}
    \color{secondary}\fontsize{21}{27}\selectfont\textbf{Reform Area} &
    \color{secondary}\fontsize{21}{27}\selectfont\textbf{Global Action} &
    \color{secondary}\fontsize{21}{27}\selectfont\textbf{Domestic Action} \\
    \rowcolor{tealbg}
    Trade & Improve multilateral trade environment & Diversify partners \& products \\
    \rowcolor{white!80!tealbg}
    Finance & Ease external financing for EMDEs & Strengthen macro frameworks \\
    \rowcolor{tealbg}
    Climate & Scale up risk mitigation & Invest in resilient infrastructure \\
    \rowcolor{white!80!tealbg}
    Investment & Catalyze private capital flows & Remove structural bottlenecks \\
    \rowcolor{tealbg}
    Jobs & Support labor mobility & Enhance skills \& market flexibility \\
  \end{tabular}
  \vspace{6pt}
  \colorbox{secondary!22}{\parbox{0.93\linewidth}{%
    \fontsize{21}{27}\selectfont\color{secondary}\textbf{1.2 billion youth} entering working age
    --- job creation is central to the Bank's mission.%
  }}
}

% ── Key Research Themes ──
\posterbox[bluecard, title={Key Research Themes}
]{name=research, column=1, between=row15 and row20}{
  \fontsize{22}{28}\selectfont
  \renewcommand{\arraystretch}{1.5}
  \centering
  \begin{tabular}{>{\bfseries\color{accent}}p{0.25\linewidth} p{0.69\linewidth}}
    \rowcolor{accent!15}
    \color{accent}\fontsize{21}{27}\selectfont\textbf{Theme} &
    \color{accent}\fontsize{21}{27}\selectfont\textbf{Selected Topics} \\
    \rowcolor{accentbg}
    Fiscal Policy & Fiscal rules (Jan.\ 2026); small states (June 2024) \\
    \rowcolor{white!80!accentbg}
    Trade & High trade costs (June 2021); COVID-19 \& value chains (June 2020) \\
    \rowcolor{accentbg}
    Commodities & Price cycles (Jan.\ 2022); energy implications (June 2022) \\
    \rowcolor{white!80!accentbg}
    Financial & Rising U.S.\ rates (June 2023); rapid debt buildup (Jan.\ 2020) \\
    \rowcolor{accentbg}
    Pandemics & COVID-19 \& inequality (Jan.\ 2022); macro effects (June 2020) \\
  \end{tabular}
}

