% ══ RIGHT COLUMN ══
% ════════════════════════════════════════════

% ── Risks to the Outlook (STRONG VISUAL WEIGHT) ──
\posterbox[riskcard, title={Risks to the Outlook}
]{name=risks, column=2, between=row5 and row12}{
  \fontsize{26}{34}\selectfont

  % Risk 1: Trade Tensions (CRITICAL)
  \fcolorbox{riskred!60}{riskred!12}{\parbox{0.93\linewidth}{%
    \vspace{5pt}%
    {\fontsize{28}{34}\selectfont\bfseries\color{riskred} \riskicon\ Trade Tensions}\\[4pt]
    {\fontsize{23}{30}\selectfont\color{textdark}
    Escalating tariffs and retaliatory measures disrupt supply chains and dampen investment.}%
    \vspace{5pt}%
  }}
  \vspace{8pt}

  % Risk 2: Financial Volatility (CRITICAL)
  \fcolorbox{riskred!60}{riskred!12}{\parbox{0.93\linewidth}{%
    \vspace{5pt}%
    {\fontsize{28}{34}\selectfont\bfseries\color{riskred} \riskicon\ Financial Market Volatility}\\[4pt]
    {\fontsize{23}{30}\selectfont\color{textdark}
    Deteriorating sentiment could tighten financing conditions, especially for EMDEs.}%
    \vspace{5pt}%
  }}
  \vspace{8pt}

  % Risk 3: Inventory Correction (WARNING)
  \fcolorbox{accent!50}{accent!12}{\parbox{0.93\linewidth}{%
    \vspace{5pt}%
    {\fontsize{28}{34}\selectfont\bfseries\color{accent} \warnicon\ Inventory Correction}\\[4pt]
    {\fontsize{23}{30}\selectfont\color{textdark}
    Firms that front-loaded purchases are drawing down stocks, reducing near-term demand.}%
    \vspace{5pt}%
  }}
  \vspace{8pt}

  % Risk 4: Climate Shocks (WARNING)
  \fcolorbox{accent!50}{accent!12}{\parbox{0.93\linewidth}{%
    \vspace{5pt}%
    {\fontsize{28}{34}\selectfont\bfseries\color{accent} \warnicon\ Climate Shocks}\\[4pt]
    {\fontsize{23}{30}\selectfont\color{textdark}
    Extreme weather threatens agricultural output and infrastructure in vulnerable regions.}%
    \vspace{5pt}%
  }}
}

% ── World Bank 2030 Strategic Priorities ──
\posterbox[highlightcard, title={World Bank 2030 Strategic Priorities}
]{name=priorities, column=2, between=row12 and row20}{
  \fontsize{24}{32}\selectfont

  % Priority 1: Health
  \fcolorbox{white!60!primary}{white}{\parbox{0.93\linewidth}{%
    \vspace{4pt}%
    {\fontsize{44}{54}\selectfont\bfseries\color{accent} 1.5 Billion People}\\[2pt]
    {\fontsize{22}{28}\selectfont\color{textdark} Health Services --- quality, affordable care}%
    \vspace{4pt}%
  }}
  \vspace{6pt}

  % Priority 2: Electricity
