    \vspace{4pt}%
    {\fontsize{44}{54}\selectfont\bfseries\color{secondary} 300 Million Farmers}\\[2pt]
    {\fontsize{22}{28}\selectfont\color{textdark} AgriConnect --- up the agricultural value chain}%
    \vspace{4pt}%
  }}
  \vspace{6pt}

  % Priority 4: Women
  \fcolorbox{white!60!primary}{white}{\parbox{0.93\linewidth}{%
    \vspace{4pt}%
