    {\fontsize{22}{28}\selectfont\color{textdark} Capital Support --- access to capital for women-led businesses}%
    \vspace{4pt}%
  }}
  \vspace{6pt}

  % Priority 5: Water
  \fcolorbox{white!60!primary}{white}{\parbox{0.93\linewidth}{%
